create table api.contract(
 id serial primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date not null,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create function priv.check_contract() returns trigger language plpgsql security definer set search_path to 'api' as $$
begin
 if not exists (select 1 from api.application a join api.status s on s.id=a.status_id where a.id=NEW.application_id and s.name='Одобрена') then
  raise exception 'договор возможен только на одобренную заявку' using errcode='check_violation';
 end if;
 return NEW;
end $$;
create trigger contract_check before insert or update on api.contract for each row execute function priv.check_contract();
create function priv.jwt_role() returns text language sql stable as $$ select current_setting('request.jwt.claims', true)::json ->> 'role' $$;
create function priv.contract_company(int) returns text language sql stable security definer set search_path to 'api' as $$ select company_inn from api.application where id=$1 $$;
create function priv.can_see_company(text) returns boolean language sql stable security definer set search_path to 'api' as $$
 select priv.jwt_role() in ('fund_admin','lawyer') or ($1 is not null and $1 = priv.my_company()) $$;
alter table api.contract enable row level security;
create policy contract_admin on api.contract for all to fund_admin using (true) with check (true);
create policy contract_lawyer on api.contract for all to lawyer using (true) with check (true);
create policy contract_applicant on api.contract for select to applicant using (priv.contract_company(application_id)=priv.my_company());
grant select,insert,update,delete on api.contract to fund_admin, lawyer;
grant select on api.contract to applicant;
grant usage on sequence api.contract_id_seq to fund_admin, lawyer;
grant usage on schema api, priv to lawyer;
grant execute on all functions in schema priv to lawyer;
grant select on api.application, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using (true);
create view api.company as select inn, legal_name, funding_limit from reg.counterparty;
grant select on api.company to lawyer, fund_admin;
create view api.limit_balance as
select c.legal_name as company, c.funding_limit, ap.approved, coalesce(ct.contracted,0) as contracted, c.funding_limit-coalesce(ct.contracted,0) as remaining
from (select a.company_inn, sum(a.amount) approved from api.application a join api.status s on s.id=a.status_id where s.name='Одобрена' group by 1) ap
join reg.counterparty c on c.inn=ap.company_inn
left join (select a.company_inn, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_inn=ap.company_inn
where priv.can_see_company(c.inn);
grant select on api.limit_balance to fund_admin, lawyer, applicant;
update api.app_user set role='lawyer' where login='lawyer1';

